node -e "
import('prettier').then(async prettier => {
  const fs = await import('node:fs');
  const config = JSON.parse(fs.readFileSync('.prettierrc', 'utf8'));
  const files = [
    'src/orchestration/tools/registry.ts',
    'src/orchestration/tools/registry.test.ts',
    'src/orchestration/tools/registry.acceptance.test.ts',
    'src/orchestration/chatOrchestrator.test.ts',
    'example/weather-tool.ts',
  ];
  for (const f of files) {
    const src = fs.readFileSync(f, 'utf8');
    const out = await prettier.format(src, {...config, filepath: f});
    if (out !== src) {
      fs.writeFileSync(f, out);
      console.log('formatted', f);
    } else {
      console.log('already formatted', f);
    }
  }
});
"

